<!-- Generated by Trae Work -->
<script setup>
/**
 * 宝物种类编辑器
 *
 * 基础设定模块：全局共用的宝物分类体系（法器/丹药/阵法/功法/御兽...）。
 * 数据来自后端 Django ArtifactCategory 模型：
 *   - name: 种类名称
 *   - description: 描述
 *   - rarity_level: 稀有度级别（SSS/SS/S/A/B/C）
 *   - world: 所属世界（null=全局共用，基础设定中一律用 null）
 */
import { ref } from 'vue'
import CrudTable from '@/components/admin/CrudTable.vue'
import { artifactCategoryApi, artifactApi } from '@/api'

/** 稀有度下拉选项 */
const RARITY_OPTIONS = [
  { value: 'SSS', label: 'SSS 级 · 至高' },
  { value: 'SS', label: 'SS 级 · 传说' },
  { value: 'S', label: 'S 级 · 史诗' },
  { value: 'A', label: 'A 级 · 稀有' },
  { value: 'B', label: 'B 级 · 优质' },
  { value: 'C', label: 'C 级 · 普通' },
]

/** 稀有度颜色映射（用于 tag 显示） */
const RARITY_COLORS = {
  SSS: 'gold',
  SS: 'gold',
  S: 'violet',
  A: 'cyan',
  B: 'emerald',
  C: 'gray',
}

/** CRUD 字段定义 */
const formFields = [
  {
    key: 'name',
    label: '种类名称',
    type: 'text',
    placeholder: '例如：法器、丹药、上古神兵',
    required: true,
    rules: [{ required: true, message: '请输入种类名称' }],
  },
  {
    key: 'rarity_level',
    label: '稀有度基准',
    type: 'select',
    options: RARITY_OPTIONS,
    default: 'B',
    help: '该种类宝物的默认稀有度级别，可在宝物编辑时单独覆盖',
  },
  {
    key: 'description',
    label: '描述',
    type: 'textarea',
    rows: 3,
    placeholder: '该宝物种类的简短说明、常见产出与代表性物品',
  },
]

/** 列表字段（表格展示） */
const listColumns = [
  {
    key: 'rarity_level',
    label: '稀有度',
    width: 90,
    align: 'center',
    sortable: true,
    render: (row) => ({
      type: 'tag',
      value: row.rarity_level || 'B',
      color: RARITY_COLORS[row.rarity_level] || 'gray',
    }),
  },
  {
    key: 'name',
    label: '种类名称',
    width: 160,
    highlight: true,
    sortable: true,
  },
  {
    key: 'description',
    label: '描述',
    flex: 1,
    ellipsis: true,
  },
  {
    key: 'artifact_count',
    label: '宝物数',
    width: 90,
    align: 'center',
    render: (row) => ({ type: 'text', value: row._artifact_count ?? '—' }),
  },
]

/** 表格操作按钮 */
const rowActions = [
  { key: 'edit', label: '✎ 编辑', type: 'primary' },
  { key: 'delete', label: '× 删除', type: 'danger', confirm: true, confirmText: '删除后该种类下所有宝物的「种类」字段会清空，确认删除？' },
]

/* ==================== 注入宝物数（富化列表） ==================== */

async function enrichRows(rows) {
  if (!rows || !rows.length) return rows
  try {
    const res = await artifactApi.list({ page_size: 500 })
    const items = res?.data?.results || []
    const counts = {}
    items.forEach((it) => {
      const catId = it.category?.id || it.category_id
      if (catId) counts[catId] = (counts[catId] || 0) + 1
    })
    return rows.map((r) => ({ ...r, _artifact_count: counts[r.id] || 0 }))
  } catch (e) {
    console.warn('[ArtifactCategoryEditor] 富化宝物数失败', e)
    return rows
  }
}
</script>

